#ifndef PRICING_H
#define PRICING_H

typedef struct {
  int price;
  int qty;
} Item;

int calc_total(const Item *items, int n);
int format_price(int amount, char *out, int size);

#endif

files.src/pricing.c:
#include <stdio.h>
#include "pricing.h"

int calc_total(const Item *items, int n) {
  int sum = 0;
  for (int i = 0; i < n; i++) sum += items[i].price * items[i].qty;
  return sum;
}

int format_price(int amount, char *out, int size) {
  return snprintf(out, size, "$%d.%02d", amount / 100, amount % 100);
}

